export type NewReservation = Omit<Reservation, 'id'>;
import { Injectable, inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { COUCH_ROW, seatId } from './seat-selection/auditorium';
import { COUCH_PRICE, seatPrice } from './pricing';
import { CheckoutValues, EMPTY_CHECKOUT } from './checkout/checkout-rules';

/** The booking in progress, kept in `sessionStorage` (section 3.1). */
export interface Booking {
  screeningId: number;
  /** Seat identifiers; a couch contributes both of its identifiers. */
  seats: string[];
  /** The checkout form values, as typed (section 7.1). */
  checkout: CheckoutValues;
  /** The customer's email address once the booking is paid. */
  paidEmail?: string;
}

/** One line of the summary: a single seat or a couch. */
export interface TicketItem {
  row: number;
  /** `<column>` for a seat, `Couch <a>-<b>` for a couch. */
  seat: string;
  seatIds: string[];
  price: number;
}

const STORAGE_KEY = 'cinescope.booking';
const SEAT_ID_PATTERN = /^R(\d+)C(\d+)$/;

@Injectable({ providedIn: 'root' })
export class BookingStore {
  read(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw === null) {
      return null;
    }
    try {
      const booking = JSON.parse(raw) as Partial<Booking>;
      if (typeof booking.screeningId !== 'number' || !Array.isArray(booking.seats)) {
        return null;
      }
      // Bookings stored before the checkout existed have no form values.
      return {
        screeningId: booking.screeningId,
        seats: booking.seats,
        checkout: { ...EMPTY_CHECKOUT, ...booking.checkout },
        paidEmail: booking.paidEmail,
      };
    } catch {
      return null;
    }
  }

  write(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }
}

/**
 * Turns seat identifiers into the tickets of the summary, ordered by row and then by column.
 * Couches only exist in the couch row, where they are always the pairs of columns 1–2, 3–4, …
 */
export function ticketsFor(seats: readonly string[]): TicketItem[] {
  const columnsByRow = new Map<number, number[]>();
  for (const id of seats) {
    const match = SEAT_ID_PATTERN.exec(id);
    if (!match) {
      continue;
    }
    const row = Number(match[1]);
    const columns = columnsByRow.get(row) ?? [];
    columns.push(Number(match[2]));
    columnsByRow.set(row, columns);
  }

  const items: TicketItem[] = [];
  for (const row of [...columnsByRow.keys()].sort((a, b) => a - b)) {
    const columns = (columnsByRow.get(row) ?? []).sort((a, b) => a - b);
    for (let index = 0; index < columns.length; ) {
      const column = columns[index];
      const next = columns[index + 1];
      if (row === COUCH_ROW && column % 2 === 1 && next === column + 1) {
        items.push({
          row,
          seat: `Couch ${column}-${next}`,
          seatIds: [seatId(row, column), seatId(row, next)],
          price: COUCH_PRICE,
        });
        index += 2;
      } else {
        items.push({ row, seat: `${column}`, seatIds: [seatId(row, column)], price: seatPrice(row) });
        index += 1;
      }
    }
  }
  return items;
}

/** Lets a route be entered only with a booking in progress for the screening in the URL. */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingStore).read();
  const screeningId = Number(route.paramMap.get('id'));
  if (booking && booking.screeningId === screeningId && booking.seats.length > 0) {
    return true;
  }
  return inject(Router).createUrlTree(['/']);
};
import { ticketsFor } from './booking';
import { formatPrice, seatPrice } from './pricing';

describe('ticketsFor', () => {
  it('lists seats and couches ordered by row and then by column', () => {
    const items = ticketsFor(['R15C3', 'R15C4', 'R7C12', 'R15C1', 'R15C2', 'R7C11', 'R1C10']);
    expect(items.map((item) => [item.row, item.seat])).toEqual([
      [1, '10'],
      [7, '11'],
      [7, '12'],
      [15, 'Couch 1-2'],
      [15, 'Couch 3-4'],
    ]);
  });

  it('describes a couch by both columns and lists its two identifiers', () => {
    const [couch] = ticketsFor(['R15C5', 'R15C6']);
    expect(couch.seat).toBe('Couch 5-6');
    expect(couch.seatIds).toEqual(['R15C5', 'R15C6']);
  });

  it('prices seats by row and a couch as one unit', () => {
    const items = ticketsFor(['R3C7', 'R8C7', 'R12C7', 'R15C1', 'R15C2']);
    expect(items.map((item) => item.price)).toEqual([25, 32, 39, 89]);
  });

  it('prices the accessible seats of row 1 like the rest of rows 1 to 5', () => {
    expect(ticketsFor(['R1C10'])[0].price).toBe(25);
    expect(seatPrice(5)).toBe(25);
  });

  it('prints prices with two decimals and the PLN suffix', () => {
    expect(formatPrice(25)).toBe('25.00 PLN');
    expect(formatPrice(121)).toBe('121.00 PLN');
  });
});

import { Component, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { EMPTY, Observable, catchError, map, switchMap, tap } from 'rxjs';
import { BookingStore } from '../booking';
import { CinemaApi, ScreeningWithMovie } from '../cinema-api.service';
import { EMPTY_CHECKOUT } from '../checkout/checkout-rules';
import { formatShowDate } from '../dates';
import { Toast } from '../toast';
import { CouchCell, SeatCell, SeatState, buildAuditorium, seatIdsOf } from './auditorium';

/** Painted state of a seat or couch: `selected` replaces a free state. */
export type DisplayState = SeatState | 'selected';

export interface SelectedRowLine {
  row: number;
  seats: string;
}

const MAX_SEATS = 10;

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly toast = inject(Toast);
  private readonly bookings = inject(BookingStore);

  /** Identifiers of the selected seats; a couch contributes both of its identifiers. */
  private readonly selectedIds = signal<ReadonlySet<string>>(new Set());

  private readonly loaded = toSignal(
    this.route.paramMap.pipe(
      map((params) => params.get('id') ?? ''),
      switchMap((id) => this.load(id)),
    ),
    { initialValue: null },
  );

  /** Null while the screening is loading; a failed load redirects to `/`. */
  readonly page = computed(() => {
    const current = this.loaded();
    if (!current) {
      return null;
    }
    return {
      showDate: formatShowDate(current.screening.date, current.screening.time),
      rows: buildAuditorium(current.screening.occupiedSeats),
    };
  });

  readonly selectedCount = computed(() => this.selectedIds().size);

  /** One `Row <r>: <seats>` line per row with a selection, rows in ascending order. */
  readonly selectedRows = computed<SelectedRowLine[]>(() => {
    const lines: SelectedRowLine[] = [];
    for (const row of this.page()?.rows ?? []) {
      const seats = row.cells.flatMap((cell) => {
        if (cell.kind !== 'seat' && cell.kind !== 'couch') {
          return [];
        }
        if (!this.isSelected(cell)) {
          return [];
        }
        return [cell.kind === 'seat' ? `${cell.column}` : `${cell.columnStart}-${cell.columnEnd}`];
      });
      if (seats.length > 0) {
        lines.push({ row: row.row, seats: seats.join(', ') });
      }
    }
    return lines;
  });

  /** Selects or deselects a seat or couch as one unit; unavailable ones are ignored. */
  toggle(cell: SeatCell | CouchCell): void {
    if (cell.state === 'unavailable') {
      return;
    }
    const ids = seatIdsOf(cell);
    const selected = new Set(this.selectedIds());
    if (this.isSelected(cell)) {
      ids.forEach((id) => selected.delete(id));
    } else {
      if (selected.size + ids.length > MAX_SEATS) {
        this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
        return;
      }
      ids.forEach((id) => selected.add(id));
    }
    this.selectedIds.set(selected);
    this.persist(selected);
  }

  /** `Cancel` clears the booking and returns to the movie list. */
  cancel(): void {
    this.bookings.clear();
    void this.router.navigate(['/']);
  }

  /** `Continue` opens the summary; it does nothing without a selected seat. */
  openSummary(): void {
    const screening = this.loaded()?.screening;
    if (!screening || this.selectedCount() === 0) {
      return;
    }
    void this.router.navigate(['/screenings', screening.id, 'summary']);
  }

  isSelected(cell: SeatCell | CouchCell): boolean {
    return this.selectedIds().has(seatIdsOf(cell)[0]);
  }

  displayState(cell: SeatCell | CouchCell): DisplayState {
    if (cell.state === 'unavailable') {
      return 'unavailable';
    }
    return this.isSelected(cell) ? 'selected' : cell.state;
  }

  private load(id: string): Observable<ScreeningWithMovie> {
    return this.api.screeningWithMovie(id).pipe(
      tap(({ screening }) => this.openBooking(screening.id)),
      catchError(() => {
        void this.router.navigate(['/']);
        return EMPTY;
      }),
    );
  }

  /**
   * Shows the booking in progress when it belongs to this screening. Otherwise a new, empty
   * booking replaces the previous one.
   */
  private openBooking(screeningId: number): void {
    const existing = this.bookings.read();
    if (existing?.screeningId === screeningId) {
      this.selectedIds.set(new Set(existing.seats));
      return;
    }
    this.bookings.write({ screeningId, seats: [], checkout: EMPTY_CHECKOUT });
    this.selectedIds.set(new Set());
  }

  /** Stores the selection in the booking, keeping the rest of it (the checkout values). */
  private persist(selected: ReadonlySet<string>): void {
    const booking = this.bookings.read();
    if (booking) {
      this.bookings.write({ ...booking, seats: [...selected] });
    }
  }
}
